using System;
using System.Collections.Generic;
using AquariusLang.Object;

namespace AquariusLang.runtime;

/// <summary>Metadata and transport tokens only. All text algorithms execute in core Wasm (runtime/texts.h).</summary>
public static class StringLibrary {
    // Ids, names and arities are shared with runtime/texts.h and hosting/string-library.mjs.
    // <generated by native/generate_portable_libraries.py>
    public const int FirstId = 30;
    public static bool IsName(string name) => name is "String" or "字串";
    internal static readonly LibraryFunction[] Definitions = {
        new("String", "From", "轉文字", 1, 1),
        new("String", "Slice", "切片", 3, 3),
        new("String", "Find", "尋找", 2, 2),
        new("String", "Contains", "包含", 2, 2),
        new("String", "StartsWith", "開頭是", 2, 2),
        new("String", "EndsWith", "結尾是", 2, 2),
        new("String", "Split", "分割", 2, 2),
        new("String", "Join", "合併", 2, 2),
        new("String", "Replace", "取代", 3, 3),
        new("String", "Trim", "修剪", 1, 1),
        new("String", "Upper", "轉大寫", 1, 1),
        new("String", "Lower", "轉小寫", 1, 1),
        new("String", "Repeat", "重複", 2, 2),
        new("String", "Code", "字元碼", 2, 2),
        new("String", "FromCode", "從字元碼", 1, 1),
        new("String", "ParseInt", "解析整數", 1, 1),
    };
    // </generated>
    public static IReadOnlyList<LibraryFunction> Functions { get; } = Array.AsReadOnly(Definitions);
    public static BuiltinObj? Resolve(int id) => id >= FirstId && id < FirstId + Definitions.Length
        ? BuiltinObj.FromPortable(id, _ => new ErrorObj("String functions require compiled Wasm execution.")) : null;
    public static ModuleObj CreateModule() => PortableModules.Create(Functions, FirstId, Resolve);
}
